function logLine(ss, logSheetName, status, message, extraObj) {
  try {
    const sh = getOrCreateSheet(ss, logSheetName);
    if (sh.getLastRow() === 0) {
      sh.appendRow(["ts", "status", "message", "json"]);
    }
    const ts = Utilities.formatDate(new Date(), TIMEZONE, "yyyy-MM-dd HH:mm:ss");
    const json = extraObj ? JSON.stringify(extraObj) : "";
    sh.appendRow([ts, status, String(message || ""), json]);
  } catch (e) {
    Logger.log("logLine failed: " + e);
  }
}

