/**
 * URL 쿼리스트링 빌드
 */
function buildUrl(base, obj) {
  const qs = Object.keys(obj)
    .map(k => `${encodeURIComponent(k)}=${encodeURIComponent(obj[k])}`)
    .join("&");
  return `${base}?${qs}`;
}

/**
 * 재시도 로직이 포함된 JSON fetch
 */
function fetchJson(url, params) {
  for (let attempt = 0; attempt <= RETRY_MAX_ADS; attempt++) {
    const res = UrlFetchApp.fetch(url, Object.assign({ muteHttpExceptions: true }, params || {}));
    const code = res.getResponseCode();
    const body = res.getContentText();

    if (code < 400) {
      try {
        return JSON.parse(body);
      } catch (e) {
        throw new Error("JSON parse error: " + e + "\n" + body);
      }
    }

    let isRateLimited = false;
    try {
      const err = JSON.parse(body).error || {};
      const msg = (err.message || "").toLowerCase();
      const ecode = err.code;
      if (
        ecode === 4 ||
        ecode === 613 ||
        msg.includes("bandwidth") ||
        msg.includes("reduce the amount") ||
        msg.includes("user request limit")
      ) {
        isRateLimited = true;
      }
    } catch (e) {}

    if (isRateLimited && attempt < RETRY_MAX_ADS) {
      const wait = RETRY_BASE_DELAY_MS * Math.pow(2, attempt) + Math.floor(Math.random() * RETRY_JITTER_MS);
      sleepMs(wait);
      continue;
    }

    throw new Error(`HTTP ${code} ${url}\n${body}`);
  }
  throw new Error("fetchJson unexpected fall-through");
}

/**
 * ============================================
 * Meta API - Ads Insights (ADSET LEVEL)
 * ============================================
 */

/**
 * 광고 계정의 Insights 데이터 조회
 */
function fetchDailyBreakdown(accessToken, actId, fromDate, toDate) {
  const url = `https://graph.facebook.com/${GRAPH_VERSION}/${encodeURIComponent(actId)}/insights`;
  const params = { method: "get", muteHttpExceptions: true };
  const query = {
    access_token: accessToken,
    time_range: JSON.stringify({ since: fromDate, until: toDate }),
    time_increment: 1,
    level: "adset",
    fields: [
      "date_start", 
      "date_stop",
      "account_id", 
      "account_name", 
      "account_currency", 
      "spend",
      "campaign_id",
      "campaign_name",
      "adset_id",
      "adset_name",
      "objective", 
      "optimization_goal",
      "impressions", 
      "reach",
      "clicks", 
      "inline_link_clicks", 
      "unique_clicks", 
      "unique_inline_link_clicks",
      "ctr", 
      "unique_ctr", 
      "inline_link_click_ctr",
      "cpc", 
      "cpm", 
      "cpp", 
      "cost_per_inline_link_click",
      "actions",
      "action_values"
    ].join(","),
    action_breakdowns: "action_type",
  };

  let next = buildUrl(url, query);
  const results = [];
  let safety = 0;

  while (next && safety++ < 50) {
    const json = fetchJson(next, params);
    if (Array.isArray(json.data)) results.push(...json.data);
    next = json.paging && json.paging.next ? json.paging.next : null;
    Utilities.sleep(600);
  }

  return results;
}

/**
 * ============================================
 * 액션 합산 로직
 * ============================================
 */

function normActionType(s) {
  return (s || "").toString().trim().toLowerCase();
}

function sumByTypes(actions, typesArr) {
  if (!Array.isArray(actions)) return 0;
  const want = new Set(typesArr.map(s => s.toLowerCase()));
  let s = 0;
  for (const a of actions) {
    const type = String(a.action_type || "").toLowerCase();
    if (want.has(type)) s += Number(a.value || 0);
  }
  return s;
}

function sumLinkClicks(actions) {
  const LINK_CLICK_CANDIDATES = [
    "link_click", 
    "click", 
    "outbound_click", 
    "onsite_conversion.messaging_link_click"
  ];
  return sumByTypes(actions, LINK_CLICK_CANDIDATES);
}

function sumLandingPageViews(actions) {
  const LANDING_PAGE_VIEW_CANDIDATES = [
    "landing_page_view",
    "offsite_conversion.fb_pixel_landing_page_view"
  ];
  return sumByTypes(actions, LANDING_PAGE_VIEW_CANDIDATES);
}

function sumLeads(actions) {
  const LEAD_CANDIDATES = [
    "lead",
    "offsite_conversion.fb_pixel_lead",
    "omni_complete_registration"
  ];
  return sumByTypes(actions, LEAD_CANDIDATES);
}

function sumCompleteRegistrations(actions) {
  const COMPLETE_REGISTRATION_CANDIDATES = [
