/**
 * 새로운 메시지 대화 상대 수량을 구하는 함수
 */
function sumNewMessageContacts(actions) {
  if (!actions || !Array.isArray(actions)) return 0;
  const match = actions.find(a => a.action_type === 'onsite_conversion.messaging_first_reply');
  return match ? Number(match.value || 0) : 0;
}

/**
 * 새로운 메시지 대화 상대 전환값(금액)을 구하는 함수
 */
function sumNewMessageValues(actionValues) {
  if (!actionValues || !Array.isArray(actionValues)) return 0;
  const match = actionValues.find(v => v.action_type === 'onsite_conversion.messaging_first_reply');
  return match ? Number(match.value || 0) : 0;
}


/**
 * ============================================
 * 목표 정규화
 * ============================================
 */

function normalizeGoal(objective, optimization_goal) {
  const obj = (objective || "").toUpperCase();
  const opt = (optimization_goal || "").toUpperCase();
  if (obj.includes("ENGAGEMENT") || opt.includes("CONVERSATIONS")) {
    return "OUTCOME_ENGAGEMENT";
  }
  return obj || opt || "";
}

/**
 * ============================================
 * 메인 로직: Ads Insights 데이터 수집
 * ============================================
 */

/**
 * 광고 데이터 수집 및 시트 저장
 * @param {Object} config - 고객 설정 객체
 * @param {string} since - 시작일 (YYYY-MM-DD)
 * @param {string} until - 종료일 (YYYY-MM-DD)
 * @param {boolean} headless - true면 alert 대신 로그만
 */
function fetchMetaInsightsWithRange(config, since, until, headless = false) {
  const runId = `${since}_${until}_${Date.now()}`;
  const startAt = new Date();

  const ss = getSpreadsheetById(config.TARGET_SHEET_ID);
  const sh = getOrCreateSheet(ss, config.ADS_SHEET_NAME || DEFAULT_ADS_SHEET_NAME);
  const logSheetName = config.ADS_LOG_SHEET || DEFAULT_ADS_LOG_SHEET;

  logLine(ss, logSheetName, "START", `fetchMetaInsights start ${runId}`, {
    since,
    until,
    accounts: config.AD_ACCOUNT_IDS.length
  });

  try {
    const headers = [
      "ad_date",
      "ad_account",
      "ad_account_name",
      "campaign_id",
      "campaign_name",
      "adset_id",
      "adset_name",
      "goal",
      "impressions",
      "reach",
      "clicks",
      "link_clicks", 
      "unique_clicks", 
      "ctr", 
      "unique_ctr", 
      "cpc", 
      "cpm", 
      "landing_page_views",
      "leads",
      "complete_registrations", 
      "contacts",
      "message_started",
      "newMessageContacts",
      "newMessageValues",
      "expense",
      "currency",
      "report_from",
      "report_to"
    ];

    if (sh.getLastRow() === 0) {
      sh.appendRow(headers);
    }

    const dateRanges = enumerateDates(since, until);
    const out = [];

    for (const actId of config.AD_ACCOUNT_IDS) {
      for (const d of dateRanges) {
        const rows = fetchDailyBreakdown(config.USER_LONG_TERM_ACCESS_TOKEN_CONST, actId, d, d);

        for (const row of rows) {
          const {
            date_start, 
            account_currency, 
            account_name, 
            spend,
            campaign_id,
            campaign_name,
            adset_id,
            adset_name,
            objective, 
            optimization_goal,
            actions,
            action_values,
            impressions, 
            reach,
            clicks, 
            unique_clicks,
            ctr, 
            unique_ctr,
            cpc, 
            cpm
          } = row;

          const linkClicks = sumLinkClicks(actions);
          const landingPageViews = sumLandingPageViews(actions);
          const leads = sumLeads(actions);
          const completeRegistrations = sumCompleteRegistrations(actions);  
          const contacts = sumContacts(actions);
          const messageStarted = sumMessageStarted(actions);
          const newMessageContacts = sumNewMessageContacts(actions);
          const newMessageValues = sumNewMessageValues(action_values);
          const goal = normalizeGoal(objective, optimization_goal);
          const expense = Number(spend || 0);

          out.push([
            date_start,
            actId.replace("act_", ""),
            account_name || "",
            campaign_id || "",
            campaign_name || "",
            adset_id || "",
            adset_name || "",
            goal,
            Number(impressions || 0),
            Number(reach || 0),
            Number(clicks || 0),
            Number(linkClicks || 0),
            Number(unique_clicks || 0),
            Number(ctr || 0),
            Number(unique_ctr || 0),
            Number(cpc || 0),
            Number(cpm || 0),
            Number(landingPageViews || 0),
            Number(leads || 0),
            Number(completeRegistrations || 0),
            Number(contacts || 0),
            Number(messageStarted || 0),
            Number(newMessageContacts || 0),
            Number(newMessageValues || 0),
            expense,
            account_currency || "",
            d, 
            d
          ]);
        }
      }
    }

    if (out.length) {
      sh.getRange(sh.getLastRow() + 1, 1, out.length, out[0].length).setValues(out);
    }

    const doneMsg = `✅ 완료: ${out.length.toLocaleString()}행 적재 (기간: ${since} ~ ${until})`;
    if (headless) Logger.log(doneMsg); else safeAlert(doneMsg);

    logLine(ss, logSheetName, "DONE", `fetchMetaInsights done ${runId}`, {
      rows: out.length,
      ms: (new Date() - startAt)
    });

    return { success: true, rows: out.length };

  } catch (err) {
    const msg = "❌ 실패: " + (err && err.message ? err.message : err);
    Logger.log(msg);
    logLine(ss, logSheetName, "ERROR", `fetchMetaInsights error ${runId}`, {
      msg,
      stack: String(err && err.stack || "")
    });
    if (!headless) safeAlert(msg);
    throw err;
  }
}

/**
 * ============================================
 * 캠페인 매핑 로직
 * ============================================
 */

function normKey(s) {
  if (s == null) return "";
  return String(s).trim().toLowerCase();
}

function idxMap(headers) {
  const m = {};
  headers.forEach((h, i) => {
    if (h) m[h] = i;
  });
  return m;
}

/**
 * campaign_id를 기준으로 index 시트의 값을 매핑
 */
function mapPageMetaByCampaignId(config) {
  const ss = getSpreadsheetById(config.TARGET_SHEET_ID);
  const mappingSheetName = config.CAMPAIGN_MAPPING_SHEET || DEFAULT_CAMPAIGN_MAPPING_SHEET;
  const adsSheetName = config.ADS_SHEET_NAME || DEFAULT_ADS_SHEET_NAME;

  // 1) 매핑 시트 읽기
  const mapSh = ss.getSheetByName(mappingSheetName);
  if (!mapSh) throw new Error(`시트를 찾을 수 없습니다: ${mappingSheetName}`);

  const mapLastRow = mapSh.getLastRow();
  const mapLastCol = mapSh.getLastColumn();
  if (mapLastRow < 2 || mapLastCol < 2) {
    throw new Error(`${mappingSheetName} 시트에 데이터가 없습니다.`);
  }

  const mapValues = mapSh.getRange(1, 1, mapLastRow, mapLastCol).getValues();
  const mapHeader = mapValues[0].map(h => String(h || "").trim());
  const hIdx = idxMap(mapHeader);

  // campaign_id 필수 확인
  const required = ["campaign_id"].concat(CAMPAIGN_MAP_KEYS);
  const miss = required.filter(k => !(k in hIdx));
  if (miss.length) {
    throw new Error(`${mappingSheetName} 헤더 누락: ${miss.join(", ")}`);
  }

  // campaign_id로 매핑 Map 생성
  const mapping = new Map();
  for (let r = 1; r < mapValues.length; r++) {
    const row = mapValues[r];
    const key = String(row[hIdx["campaign_id"]] || "").trim();
    if (!key) continue;
    const obj = {};
    for (const k of CAMPAIGN_MAP_KEYS) {
      obj[k] = row[hIdx[k]] ?? "";
    }
    mapping.set(key, obj);
  }

  // 2) 대상 시트 준비
  const targetSh = ss.getSheetByName(adsSheetName);
  if (!targetSh) throw new Error(`시트를 찾을 수 없습니다: ${adsSheetName}`);
  if (targetSh.getLastRow() === 0) {
    throw new Error(`${adsSheetName} 시트에 데이터가 없습니다.`);
  }

  const tgtLastRow = targetSh.getLastRow();
  const tgtLastCol = targetSh.getLastColumn();
  const tgtHeader = targetSh.getRange(1, 1, 1, tgtLastCol).getValues()[0]
    .map(h => String(h || "").trim());
  let tIdx = idxMap(tgtHeader);

  // campaign_id 컬럼 확인
  if (!("campaign_id" in tIdx)) {
    throw new Error(`${adsSheetName} 헤더에 'campaign_id' 컬럼이 없습니다.`);
  }
  const campaignIdCol = tIdx["campaign_id"] + 1;

  // 없는 매핑 컬럼 추가
  const newHeadersToAppend = [];
  for (const k of CAMPAIGN_MAP_KEYS) {
    if (!(k in tIdx)) newHeadersToAppend.push(k);
  }
  if (newHeadersToAppend.length) {
    targetSh.getRange(1, tgtLastCol + 1, 1, newHeadersToAppend.length)
      .setValues([newHeadersToAppend]);
  }

  // 최신 헤더 재계산
  const newLastCol = targetSh.getLastColumn();
  const freshHeader = targetSh.getRange(1, 1, 1, newLastCol).getValues()[0]
    .map(h => String(h || "").trim());
  tIdx = idxMap(freshHeader);

  // 3) campaign_id 값 읽기
  const campaignIdVals = targetSh.getRange(2, campaignIdCol, tgtLastRow - 1, 1)
    .getValues()
    .map(v => String(v[0] || "").trim());

  // 4) 각 매핑 컬럼에 값 채우기
  const updatedCols = [];
  for (const k of CAMPAIGN_MAP_KEYS) {
    const colIdx1 = tIdx[k] + 1;
    const outCol = new Array(tgtLastRow - 1);

    for (let i = 0; i < campaignIdVals.length; i++) {
      const key = campaignIdVals[i];
      const m = key ? mapping.get(key) : null;
      outCol[i] = m ? (m[k] ?? "") : "";
    }

    targetSh.getRange(2, colIdx1, tgtLastRow - 1, 1)
      .setValues(outCol.map(v => [v]));
    updatedCols.push(k);
  }

  return { rows: tgtLastRow - 1, updatedCols };
}

